import{_ as t,o,c as n,ah as a}from"./chunks/framework.Ck7Wg-8g.js";const r="/projects/24-Channel-Servo-Controller/en/latest/assets/image2.DoSPCqI-.png",s="data:image/png;base64,",i="/projects/24-Channel-Servo-Controller/en/latest/assets/image4.Baxfe_oz.png",l="/projects/24-Channel-Servo-Controller/en/latest/assets/image5.DfvcWzp6.png",c="/projects/24-Channel-Servo-Controller/en/latest/assets/image6.BETcaaNK.png",d="/projects/24-Channel-Servo-Controller/en/latest/assets/image7.t0s_Y4Hc.png",h="/projects/24-Channel-Servo-Controller/en/latest/assets/image8.neDqTaZU.png",m="/projects/24-Channel-Servo-Controller/en/latest/assets/image9.BH06ktoP.png",g="/projects/24-Channel-Servo-Controller/en/latest/assets/image10.C4SERrrc.png",p="data:image/png;base64,",u="/projects/24-Channel-Servo-Controller/en/latest/assets/image12.CE-t5KV1.png",A="/projects/24-Channel-Servo-Controller/en/latest/assets/image13.DI2jslP1.png",y="/projects/24-Channel-Servo-Controller/en/latest/assets/image14.CxsYzwk5.png",w="/projects/24-Channel-Servo-Controller/en/latest/assets/image15.CHxYgiN5.png",C="/projects/24-Channel-Servo-Controller/en/latest/assets/image16.uRDwCphD.png",f="/projects/24-Channel-Servo-Controller/en/latest/assets/image17.Dlu8ym5G.png",b="data:image/png;base64,",P="/projects/24-Channel-Servo-Controller/en/latest/assets/image9.DfsHAU5K.png",v="/projects/24-Channel-Servo-Controller/en/latest/assets/image10.D1HYrlbP.png",_="/projects/24-Channel-Servo-Controller/en/latest/assets/image11.CV3EHktE.png",x="/projects/24-Channel-Servo-Controller/en/latest/assets/image12.DnhAN_cj.png",S="/projects/24-Channel-Servo-Controller/en/latest/assets/image13.CyXCCnVj.png",E="/projects/24-Channel-Servo-Controller/en/latest/assets/image24.Def1Iz9K.png",T="/projects/24-Channel-Servo-Controller/en/latest/assets/image25.BVE-mbm9.png",M="/projects/24-Channel-Servo-Controller/en/latest/assets/image26.wtO0nU5Z.png",q="/projects/24-Channel-Servo-Controller/en/latest/assets/image27.0-ZEi8__.png",J=JSON.parse('{"title":"3. MP3 Module User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3_MP3_Module.md","filePath":"docs/3_MP3_Module.md"}'),z={name:"docs/3_MP3_Module.md"};function V(I,e,j,R,k,Y){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-mp3-module-user-manual" tabindex="-1">3. MP3 Module User Manual <a class="header-anchor" href="#_3-mp3-module-user-manual" aria-label="Permalink to &quot;3. MP3 Module User Manual&quot;">​</a></h1><img loading="lazy" height="379" width="651" src="'+r+'" class="common_img"><h2 id="_3-1-product-introduction" tabindex="-1">3.1 Product Introduction <a class="header-anchor" href="#_3-1-product-introduction" aria-label="Permalink to &quot;3.1 Product Introduction&quot;">​</a></h2><p>The MP3 module contains the TF card, which can store hundreds of music and audio files.This facilitates the robot&#39;s speech and singing. The module also has a loudspeaker (speaker), which is loud and easy to install. Its user-friendly wiring can provide you a better experience.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>This product needs to be used with a 24-channel or 32-channel servo controller. A 32-channel servo controller is used for demonstration.</p></section><h2 id="_3-2-port-instruction" tabindex="-1">3.2 Port Instruction <a class="header-anchor" href="#_3-2-port-instruction" aria-label="Permalink to &quot;3.2 Port Instruction&quot;">​</a></h2><img loading="lazy" height="19" width="93" src="'+s+'" class="common_img"><img loading="lazy" height="483" width="483" src="'+i+'" class="common_img"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Name</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">RX</td><td style="text-align:center;">Receive pin: receive data.</td></tr><tr><td style="text-align:center;">TX</td><td style="text-align:center;">Transmit pin: send data.</td></tr><tr><td style="text-align:center;">GND</td><td style="text-align:center;">Ground pin</td></tr><tr><td style="text-align:center;">NC</td><td style="text-align:center;">Floating pin: not connected to any other port.</td></tr><tr><td style="text-align:center;">3.3V</td><td style="text-align:center;">Power port: receive 3.3V power supply.</td></tr></tbody></table><h2 id="_3-3-product-usage" tabindex="-1">3.3 Product Usage <a class="header-anchor" href="#_3-3-product-usage" aria-label="Permalink to &quot;3.3 Product Usage&quot;">​</a></h2><h3 id="_3-3-1-download-music" tabindex="-1">3.3.1 Download Music <a class="header-anchor" href="#_3-3-1-download-music" aria-label="Permalink to &quot;3.3.1 Download Music&quot;">​</a></h3><p>(1) Please prepare a card reader before using this module. It is convenient for you to upload music to the TF card. Insert the TF card into the card reader&#39;s slot. Then, connect the card reader to the USB port of your computer.</p><img loading="lazy" height="447" width="776" src="'+l+'" class="common_img"><p>(2) After connecting it to the computer, the drive pops up in <strong>&quot;My Computer&quot;</strong>. Double-click to enter.</p><img loading="lazy" height="497" width="1134" src="'+c+'" class="common_img"><p>(3) After opening the drive, create a folder named <strong>&quot;mp3&quot;</strong> to store MP3 music. The MP3 module will play the music based on the music in it.</p><img loading="lazy" height="497" width="1134" src="'+d+'" class="common_img"><p>(4) You can drag your favorite music into this folder. Taking MP3 music as an example, after dragging it into the folder, rename the music in the format of four digits <strong>&quot;000X&quot;</strong>. For example, if it is the music 1, rename it to <strong>&quot;0001.mp3&quot;</strong>; if it is the music 10, rename it to <strong>&quot;0010.mp3&quot;</strong>.</p><img loading="lazy" height="446" width="924" src="'+h+'" class="common_img"><p>(5) If you want to delete or modify the music number, you can also perform this operation in the drive.</p><p id="anchor_3_3_2"></p><h3 id="_3-3-2-connection-instruction" tabindex="-1">3.3.2 Connection Instruction <a class="header-anchor" href="#_3-3-2-connection-instruction" aria-label="Permalink to &quot;3.3.2 Connection Instruction&quot;">​</a></h3><p>(1) Connect the speaker to the MP3 module. Please ensure that the positive terminal on the speaker is connected to the &quot;spk+&quot; pin on the MP3 module.</p><img loading="lazy" height="458" width="1101" src="'+m+'" class="common_img"><img loading="lazy" height="283" width="1098" src="'+g+'" class="common_img"><p>(2) After uploading music to the TF card, disconnect the USB connection. Remove the TF card, and insert it into the slot of the MP3 module. Please note that the slot has a spring inside. You should feel a <strong>&#39;click&#39;</strong> sound when the card is successfully inserted.</p><img loading="lazy" height="27" width="68" src="'+p+'" class="common_img"><img loading="lazy" height="408" width="709" src="'+u+'" class="common_img"><p>(3) Connect the MP3 module to the 32-channel servo controller, aligning the pins with the corresponding holes.</p><img loading="lazy" height="399" width="1131" src="'+A+'" class="common_img"><h2 id="_3-4-pc-software-introduction" tabindex="-1">3.4 PC Software Introduction <a class="header-anchor" href="#_3-4-pc-software-introduction" aria-label="Permalink to &quot;3.4 PC Software Introduction&quot;">​</a></h2><h3 id="_3-4-1-setup-hardware-environment" tabindex="-1">3.4.1 Setup Hardware Environment <a class="header-anchor" href="#_3-4-1-setup-hardware-environment" aria-label="Permalink to &quot;3.4.1 Setup Hardware Environment&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>This product needs to be used with a 24-channel or 32-channel servo controller. A 32-channel servo controller is used for demonstration.</p></section><p>The required materials are shown below:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Name</th><th style="text-align:center;">Qty</th></tr></thead><tbody><tr><td style="text-align:center;">32-Channel servo controller</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">MP3 module, including TF card and speaker</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">USB cable</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Battery connection cable</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">7.4V lithium battery</td><td style="text-align:center;">1</td></tr></tbody></table><p>(1) Please refer to <a href="#anchor_3_3_2">3.3.2 Connection Instruction</a> to connect the MP3 module to the servo controller. The pins must be matched correctly.</p><img loading="lazy" height="359" width="457" src="'+y+'" class="common_img"><p>(2) Connect the connection cable on the speaker to the MP3 module, as shown below:</p><img loading="lazy" height="463" width="1197" src="'+w+'" class="common_img"><p>(3) Connect the battery connection cable to the power interface on the servo controller, and connect the lithium battery.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>connect the red wire to <strong>&quot;+&quot;</strong>, and the black wire to <strong>&quot;-&quot;</strong>. The positive and negative terminals must be matched correctly.</p></section><img loading="lazy" height="811" width="1123" src="'+C+'" class="common_img"><p>(4) Connect the servo controller to your PC with the USB cable. Switch the servo controller on.</p><img loading="lazy" height="714" width="1196" src="'+f+'" class="common_img"><h3 id="_3-4-2-setup-software-environment" tabindex="-1">3.4.2 Setup Software Environment <a class="header-anchor" href="#_3-4-2-setup-software-environment" aria-label="Permalink to &quot;3.4.2 Setup Software Environment&quot;">​</a></h3><p>(1) Locate the <strong>Hiwonder Servo Control Steup.exe</strong> in <a href="./Appendix.html">Appendix-&gt;PC Software</a>, and double-click to install it.</p><img loading="lazy" height="33" width="261" src="'+b+'" class="common_img"><p>(2) Install the software according to the installation prompts.</p><img loading="lazy" height="162" width="349" src="'+P+'" class="common_img"><img loading="lazy" height="415" width="582" src="'+v+'" class="common_img"><img loading="lazy" height="415" width="582" src="'+_+'" class="common_img"><img loading="lazy" height="415" width="582" src="'+x+'" class="common_img"><img loading="lazy" height="415" width="582" src="'+S+'" class="common_img"><h3 id="_3-4-3-play-music" tabindex="-1">3.4.3 Play music <a class="header-anchor" href="#_3-4-3-play-music" aria-label="Permalink to &quot;3.4.3 Play music&quot;">​</a></h3><p>For more detailed instruction on the PC software interface, please access <a href="./1_User_Manual_formatted.html">1.LSC-24 Servo Controller User Manual</a>.</p><p>(1) Connect the PC software to the MP3 module with a USB data cable. Playing music with the MP3 module is realized by calling the action group function in the PC software. Therefore, you need to ensure that the PC software has the corresponding action group. This allows the desired music from the TF card to be played.</p><img loading="lazy" height="766" width="1296" src="'+E+'" class="common_img"><p>(2) Take <strong>&quot;0010.MP3&quot;</strong> in the TF card as an example. Its corresponding action group that needs to be called in the PC software is action group 10. Therefore, before calling the action group, edit an action and download it to action group 10. Let&#39;s add the initial action to the action details list in the PC software.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the servo controller connected already has a downloaded action group in the corresponding number, there is no need to download it again. You can proceed to step 4 to directly call the action group to play music.</p></section><img loading="lazy" height="766" width="1296" src="'+T+'" class="common_img"><p>(3) Select the action group 10 in the action group list. Click the <strong>&quot;Download&quot;</strong> button to download the action to the corresponding number.</p><img loading="lazy" height="470" width="439" src="'+M+'" class="common_img"><p>(4) After downloading the action group, select the corresponding action group number. Click <strong>&quot;Run action&quot;</strong>. The corresponding music will be played. If you want to stop the music, click the <strong>&quot;Stop&quot;</strong> on the interface. The same steps can be followed for playing others.</p><img loading="lazy" height="470" width="721" src="'+q+'" class="common_img">',64)])])}const H=t(z,[["render",V]]);export{J as __pageData,H as default};
